await consumer.run({
  autoCommit: false, // Disable auto-commit to prevent premature acknowledgment
  eachMessage: async ({ topic, partition, message }) => {
    // 1. Process business logic within DB transaction
    await db.transaction(async (trx) => {
      await processOrderEvent(trx, message.value.toString());
    });

    // 2. Commit offset only AFTER database transaction commits durably
    await consumer.commitOffsets([{
      topic,
      partition,
      offset: (BigInt(message.offset) + 1n).toString(), // Point to next record
    }]);
  },
});
